<script setup>
import {Link,usePage} from '@inertiajs/vue3';import {computed,ref} from 'vue';const page=usePage(),open=ref(false),panel=computed(()=>page.props.adminPanel||{menu:[]});const active=h=>{const b=String(h).split('?')[0].split('#')[0];return page.url===b||page.url.startsWith(b+'/')};
</script><template><div class="lf-admin"><div v-if="open" class="fixed inset-0 z-[80] bg-black/45 lg:hidden" @click="open=false"></div><aside class="lf-admin-sidebar" :class="{open}"><div class="lf-admin-brand"><span class="lf-admin-logo">LF</span><span><strong>LFAMILIA ADMIN</strong><small>Top Up Game Solution</small></span></div><div class="lf-admin-user"><strong>{{panel.admin?.name||'Administrator'}}</strong><span>{{panel.admin?.role||'ADMIN'}} · {{panel.admin?.email}}</span></div><nav class="lf-admin-menu"><Link v-for="x in panel.menu" :key="x.href" :href="x.href" :class="{active:active(x.href)}" @click="open=false">{{x.label}}</Link></nav><div class="lf-admin-help"><strong>Butuh bantuan?</strong><p>Buka Layanan Pelanggan untuk melihat dan menangani tiket.</p></div></aside><div class="lf-admin-body"><header class="lf-admin-top"><button class="lf-admin-toggle" @click="open=true">☰</button><strong class="text-[11px] text-slate-600">Panel Operasional LFAMILIA STORE</strong><nav><Link v-if="panel.can_notifications" href="/admin/notifications">Notifikasi<span v-if="panel.unread_notifications"> ({{panel.unread_notifications}})</span></Link><Link href="/">Lihat Toko</Link></nav></header><main class="lf-admin-content"><slot/></main></div></div></template>